hZmvdu/ry3OutYBUATlIW0ZNsO8dZ9eZRcGnHjDfyRDqCWnswBvX\n/vFPR4YhbT3yA8G7wafMJY+7tj2RgXRBN6RlDz64+tE3usYF+54xN2W+2r2v78649gJSBeQg\n2VvN/aeNs1tN8N3FrjCrIyE9by5L32gbFoLUesbb3F+1uN3MyM7baOYEy8k9f0bqGud+SWHc\nXza1+bXufVR6QKqAMpDaTjj2g+OsHXNk8A8fHb4rEtKf3Tes5ebUbkhXDnokM+b9Bwffc+6a\n39Zx6Ds7rN0woFdI9oTD0j9xPZt+g9e1r49OtyYDUgWUgWR/M2BAGtIDB5x3/4OfCeBEQWo9\n5qj7f3PdWWeNenhPFtK95hPBL8Af2mh/PfjEu36xYPBMa79g/vVH3zy2oXdIqw74wN0r3vXW\nraF9VHJAqoCykOwsE/yB7JoPjRh6yndtNCS77rThb7t818pDD9mQhXR19lcFN1v76LmjBr/r\nlvQ3lvbPHz7khJ9cOaRrfhQk+8Cpw9/68edsaB+VHJCIBAGJSBCQiAQBiUgQkIgEAYlIEJCI\nBAGJSBCQiAQBiUgQkIgEAYlIEJCIBP1/Zf4dzT/wRjAAAAAASUVORK5CYII="},"metadata":{"image/png":{"width":420,"height":420}}}],"source":["# Load necessary libraries\n","library(ggplot2)\n","library(dplyr)\n","library(scales)\n","\n","# Load the diamonds dataset\n","data(\"diamonds\")\n","\n","# 1. Data Summarization\n","# Summary statistics for the entire dataset\n","summary(diamonds)\n","\n","# Insight:\n","# The dataset contains 53,940 rows and 10 columns.\n","# Key observations: The price ranges from $326 to $18,823, while carat sizes range from 0.2 to 5.01.\n","# Most diamonds fall into high \"cut\" grades (like Ideal and Premium).\n","\n","# Count of diamonds by cut\n","diamonds %>%\n","  count(cut)\n","\n","# Insight:\n","# \"Ideal\" and \"Premium\" cuts are the most frequent, indicating higher quality cuts dominate the dataset.\n","\n","# 2. Data Visualization\n","# Visualize the distribution of diamond prices\n","ggplot(diamonds, aes(x = price)) +\n","  geom_histogram(fill = \"skyblue\", bins = 50) +\n","  scale_x_continuous(labels = dollar) +\n","  labs(title = \"Distribution of Diamond Prices\", x = \"Price ($)\", y = \"Count\")\n","\n","# Insight:\n","# The majority of diamond prices are skewed toward the lower end, with a long tail of higher prices.\n","\n","# Visualize the relationship between carat and price\n","ggplot(diamonds, aes(x = carat, y = price)) +\n","  geom_point(alpha = 0.4, color = \"blue\") +\n","  scale_y_continuous(labels = dollar) +\n","  labs(title = \"Scatter Plot of Carat vs. Price\", x = \"Carat\", y = \"Price ($)\")\n","\n","# Insight:\n","# As the carat size increases, the price generally increases, but there is considerable variability.\n","\n","# Boxplot for price distribution by cut\n","ggplot(diamonds, aes(x = cut, y = price)) +\n","  geom_boxplot(fill = \"lightgreen\") +\n","  scale_y_continuous(labels = dollar) +\n","  labs(title = \"Price Distribution by Cut\", x = \"Cut\", y = \"Price ($)\")\n","\n","# Insight:\n","# Higher quality cuts (like Ideal and Premium) tend to have a narrower price range, while lower quality cuts have wider price distributions.\n","\n","# 3. Data Normalization\n","# Normalize the \"price\" column using Min-Max Scaling\n","diamonds <- diamonds %>%\n","  mutate(price_normalized = (price - min(price)) / (max(price) - min(price)))\n","\n","# Summary statistics for the normalized price\n","summary(diamonds$price_normalized)\n","\n","# Insight:\n","# The normalized price now ranges from 0 to 1, making it easier to compare price values across different scales.\n","\n","# Visualize the normalized price distribution\n","ggplot(diamonds, aes(x = price_normalized)) +\n","  geom_histogram(fill = \"coral\", bins = 50) +\n","  labs(title = \"Distribution of Normalized Diamond Prices\", x = \"Normalized Price\", y = \"Count\")\n","\n","# Insight:\n","# The normalized distribution retains the original shape, showing most normalized prices cluster toward the lower end.\n","\n","# 4. Grouping and Aggregating (Additional Insight)\n","# Average price by cut\n","avg_price_by_cut <- diamonds %>%\n","  group_by(cut) %>%\n","  summarize(avg_price = mean(price), avg_carat = mean(carat))\n","\n","print(avg_price_by_cut)\n","\n","# Insight:\n","# Diamonds with higher quality cuts (like Ideal) tend to have higher average prices and smaller carat sizes."]},{"cell_type":"code","source":[],"metadata":{"id":"oQz95pGxFKni"},"execution_count":null,"outputs":[]}]}